#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# NCERTCHEM, setup stage A: what Accounts and Progress need before the sign-in code can run.
# Run it from the repository root:  bash scripts/setup-accounts.sh
#
# It writes two files, both ignored by git:
#   .env.local        values the site reads. All of them are public by design.
#   supabase/.env     the Google client secret, for the local Supabase only.
# The database password and the Supabase secret key are never written anywhere.

cd "$(dirname "$0")/.."
TOTAL_STAGES=8
SITE_ENV=".env.local"
SUPABASE_ENV="supabase/.env"
DEV_ORIGIN="http://localhost:3000"
E2E_ORIGIN="http://localhost:3200"

banner "NCERTCHEM setup A: Supabase, Google sign-in and Docker"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Docker access for your user"
say "The local Supabase used by the end-to-end tests runs in Docker."
if docker ps >/dev/null 2>&1; then
  say "${GREEN}✓${RESET} Docker already answers for $USER. Nothing to do."
else
  say "Docker is installed, but your user may not use it yet."
  say "The fix adds $USER to the 'docker' group. It needs your sudo password."
  warn "Members of the docker group have root-equivalent access to this machine."
  if confirm "Run: sudo usermod -aG docker $USER ?"; then
    sudo usermod -aG docker "$USER"
    say "${GREEN}✓${RESET} $USER is now in the docker group."
    note "The group reaches only new login sessions: log out and back in (or restart),"
    note "then check with: docker ps"
    SKIPPED+=("Docker: log out and back in, then check 'docker ps' works")
  else
    SKIPPED+=("Docker access: sudo usermod -aG docker $USER, then log out and in")
  fi
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Supabase: create the project"
say "Use the Google account you intend to keep for NCERTCHEM, for Supabase and Google Cloud alike."
open_url "https://supabase.com/dashboard/new"
step "Sign in (or sign up), and pick or create an organisation on the Free plan."
step "Project name: ncertchem"
step "Database password: press 'Generate a password', and save it in your password manager."
note "  This wizard never asks for it again except once in stage 7, and never stores it."
step "Region: South Asia (Mumbai)."
step "Press 'Create new project' and wait until the dashboard says it is ready (a minute or two)."
say ""
say "The project ref is the 20 lowercase letters in the dashboard address:"
note "  https://supabase.com/dashboard/project/<ref>"
while :; do
  ask SUPABASE_PROJECT_REF "Paste the project ref:"
  [[ "$SUPABASE_PROJECT_REF" =~ ^[a-z]{20}$ ]] && break
  warn "A project ref is exactly 20 lowercase letters. Try again."
done
ENV_FILE="$SITE_ENV"
write_env SUPABASE_PROJECT_REF "$SUPABASE_PROJECT_REF"
write_env NEXT_PUBLIC_SUPABASE_URL "https://${SUPABASE_PROJECT_REF}.supabase.co"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Supabase: the publishable key"
say "The site uses the publishable key. It is safe in a browser: the database rules decide what it may do."
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/settings/api-keys"
step "Find 'Publishable key' (it starts with sb_publishable_). Create one if the page offers to."
step "Copy it. Do NOT copy the secret key (sb_secret_...) or the legacy service_role key."
while :; do
  ask NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY "Paste the publishable key:"
  [[ "$NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY" == sb_publishable_* ]] && break
  warn "That does not start with sb_publishable_. Copy the publishable key, not another one."
done
write_env NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY "$NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Google Cloud: the sign-in screen"
say "Google shows this screen when a Learner signs in. It stays in 'Testing' until the public launch."
open_url "https://console.cloud.google.com/projectcreate"
step "Create a project named ncertchem, and make sure it is selected at the top of the page."
pause "Press Enter when the project exists and is selected."
open_url "https://console.cloud.google.com/auth/overview"
step "Press 'Get started' if Google asks. App name: NCERTCHEM. Support email: your own."
step "Audience: External. Contact email: your own. Agree, and press Create."
step "Audience page: leave Publishing status on 'Testing'. Under 'Test users', add your own Google"
note "  address and any Google address you want to try signing in with. Only these can sign in for now."
step "Data access page: Add or remove scopes → tick openid, .../auth/userinfo.email and"
note "  .../auth/userinfo.profile. Nothing else. Save."
note "The privacy policy link and the live domain are added in setup stage B, before launch."
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Google Cloud: the sign-in client"
open_url "https://console.cloud.google.com/auth/clients/create"
step "Application type: Web application. Name: NCERTCHEM web."
step "Authorized JavaScript origins: add both of these:"
note "    ${DEV_ORIGIN}"
note "    ${E2E_ORIGIN}"
step "Authorized redirect URIs: add"
note "    https://${SUPABASE_PROJECT_REF}.supabase.co/auth/v1/callback"
step "Press Create. Google shows the Client ID and the Client secret."
while :; do
  ask NEXT_PUBLIC_GOOGLE_CLIENT_ID "Paste the Client ID:"
  [[ "$NEXT_PUBLIC_GOOGLE_CLIENT_ID" == *.apps.googleusercontent.com ]] && break
  warn "A Client ID ends in .apps.googleusercontent.com. Try again."
done
ENV_FILE="$SITE_ENV"
write_env NEXT_PUBLIC_GOOGLE_CLIENT_ID "$NEXT_PUBLIC_GOOGLE_CLIENT_ID"
ENV_FILE="$SUPABASE_ENV"
ask_secret SUPABASE_AUTH_EXTERNAL_GOOGLE_CLIENT_SECRET "Paste the Client secret (hidden):"
write_env SUPABASE_AUTH_EXTERNAL_GOOGLE_CLIENT_ID "$NEXT_PUBLIC_GOOGLE_CLIENT_ID"
write_env SUPABASE_AUTH_EXTERNAL_GOOGLE_CLIENT_SECRET "$SUPABASE_AUTH_EXTERNAL_GOOGLE_CLIENT_SECRET"
chmod 600 "$SUPABASE_ENV"
ENV_FILE="$SITE_ENV"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Supabase: turn on Google sign-in"
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/auth/providers"
step "Open Google in the provider list and switch it on."
step "Client IDs: paste ${NEXT_PUBLIC_GOOGLE_CLIENT_ID}"
step "Client Secret: paste the secret from stage 5 (it is also in ${SUPABASE_ENV})."
step "Leave 'Skip nonce check' OFF. Save."
open_url "https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}/auth/url-configuration"
step "Site URL: ${DEV_ORIGIN}   (stage B changes it to the live address). Save."
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Apply the Progress database rules"
say "This creates the two Progress tables, their rules (each Account sees only its own rows) and"
say "Delete Account, from supabase/migrations/. The Supabase CLI asks you to sign in once in the"
say "browser, then for the database password from stage 2."
npx supabase login
npx supabase link --project-ref "$SUPABASE_PROJECT_REF"
say ""
say "What would be applied:"
npx supabase db push --remote --dry-run
if confirm "Apply these migrations to the ncertchem project now?"; then
  npx supabase db push --remote
else
  SKIPPED+=("Database rules: npx supabase db push --remote")
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Check that it all answers"
say "A visitor who is not signed in must be refused by the Progress tables."
code=$(curl -s -o /dev/null -w '%{http_code}' \
  "https://${SUPABASE_PROJECT_REF}.supabase.co/rest/v1/answered_checks?select=section_slug&limit=1" \
  -H "apikey: ${NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY}" || echo "000")
case "$code" in
  401|403) say "${GREEN}✓${RESET} The table exists and refuses a visitor ($code), as it should." ;;
  404)     warn "The table was not found (404). Were the migrations applied in stage 7?"
           SKIPPED+=("Database rules: answered_checks not found") ;;
  200)     warn "A visitor could read the table (200). Stop here and tell Claude."
           SKIPPED+=("Database rules: answered_checks readable by a visitor") ;;
  *)       warn "Unexpected answer ($code). Check the project ref and the publishable key."
           SKIPPED+=("Check: unexpected HTTP $code from answered_checks") ;;
esac
pause

finish
note "Next: tell Claude that setup A is done. Stage B (Vercel, domain, publishing Google sign-in)"
note "comes before the public launch."
